<div class="flex items-center justify-between mb-3"><h5 class="text-sm font-semibold text-slate-300">Configuracion SMTP</h5><button @click="openSmtp(0)" class="px-3 py-1.5 bg-blue-500/15 text-blue-400 border border-blue-500/30 rounded-lg text-xs font-semibold hover:bg-blue-500/25 transition flex items-center gap-1"><i data-lucide="plus" class="w-3.5 h-3.5"></i> Anadir Cuenta</button></div><div class="overflow-x-auto rounded-xl border border-slate-800"><table class="w-full text-xs"><thead><tr class="bg-slate-900 text-slate-400 text-[10px] uppercase tracking-wider"><th class="px-3 py-2 text-left">Emisor</th><th class="px-3 py-2 text-left hidden sm:table-cell">Host</th><th class="px-3 py-2 text-center">Envios / Limite</th><th class="px-3 py-2 text-center">Estado</th><th class="px-3 py-2 text-right">Acciones</th></tr></thead><tbody id="smtpBody"><tr><td colspan="5" class="px-3 py-8 text-center text-slate-600">Cargando...</td></tr></tbody></table></div>